lean_object* solve_result_to_lean(clingo_solve_result_bitset_t v) {
  lean_object * obj = lean_alloc_ctor(0, 0, 4);
  uint8_t * sp = lean_ctor_scalar_cptr(obj);
  sp[0] = (v & 1) != 0;
  sp[1] = (v & 2) != 0;
  sp[2] = (v & 4) != 0;
  sp[3] = (v & 8) != 0;
  return obj;
}

clingo_solve_result_bitset_t lean_to_solve_result(b_lean_obj_arg obj) {
  uint8_t * sp = lean_ctor_scalar_cptr(obj);
  clingo_solve_result_bitset_t v = 0;
  if (sp[0]) {
    v |= 1;
  }
  if (sp[1]) {
    v |= 2;
  }
  if (sp[2]) {
    v |= 4;
  }
  if (sp[3]) {
    v |= 8;
  }
  return v;
}

